class Leksak:

    def __init__(self, färg, åldersgräns):
        self.färg = färg
        self.åldersgräns = åldersgräns

    def __str__(self):
        text = "En leksak för barn över " + str(self.åldersgräns) + " år"
        return text + " med färgen " + self.färg + "."


class Boll(Leksak):

    def studsa(self):
        print("Bollen med färgen " + self.färg + " studsar!")


def main():
    leksak = Leksak("grön", 8)
    print(leksak)
    boll = Boll("röd", 3)
    print(boll)
    boll.studsa()

main()
